import dotenv from "dotenv";
import * as path from "path";
import "reflect-metadata"; // Needed by type-graphql

// FIXME: Resolve against project root, not module as this is brittle
dotenv.config({
  path: path.resolve(__dirname, "../../.env"),
});

import logger from "./logger";
import rebuildSites from "./rebuild-sites";
import createServer from "./server";

process.on("SIGINT", () => {
  logger.info("\nGracefully shutting down from SIGINT (Ctrl-C)");

  process.exit(1);
});

(async () => {
  logger.debug("Starting application");

  try {
    await createServer();

    logger.debug("Running");

    if (process.env.NODE_ENV === "production") {
      rebuildSites(process.env.REBUILD_SITES);
    }
  } catch (e) {
    logger.error("Failed to start");
    logger.error(e.stack);
  }
})();

import request from "request";
import logger from "./logger";

// Expects a comma separated string
function rebuildSites(urls) {
  urls.split(",").forEach(rebuildSite);
}

function rebuildSite(url) {
  request.post(url, err => {
    if (err) {
      return logger.error(err);
    }

    return logger.info(`rebuilt ${url}`);
  });
}

export default rebuildSites;

// https://github.com/amazeeio/lagoon/blob/master/services/api/src/logger.js
import * as fs from "fs";
import * as path from "path";
import { isString } from "util";
import { createLogger, format, transports } from "winston";

// Create the logs directory if it doesn't exist yet.
const directory = path.join(".", "logs");
if (!fs.existsSync(directory)) {
  fs.mkdirSync(directory);
}

const ignorePingAndMedia = format(info => {
  const message = info.message;

  if (
    isString(message) &&
    ["GET /ping ", "GET /media"].some(match => message.includes(match))
  ) {
    return false;
  }

  return info;
});

const logger = createLogger({
  exitOnError: false,
  format: format.combine(ignorePingAndMedia(), format.json()),
  transports: [
    new transports.Console({
      level: "debug",
      handleExceptions: true,
    }),
  ],
});

export default logger;

import createApp from "./app";
import logger from "./logger";

const normalizePort = (value: string) => {
  const port = Number(value);

  if (!isNaN(port) && port > 0) {
    return port;
  }

  return false;
};

async function createServer() {
  logger.debug("Starting to boot the server.");

  const port = normalizePort(process.env.PORT || "3000");
  const app = await createApp();
  let server;

  try {
    server = app.listen(port, () =>
      logger.debug(
        `Finished booting the server. The API is reachable at http://localhost:${port.toString()}/graphql.`
      )
    );
  } catch (err) {
    logger.error(err);

    process.exit(1);
  }

  // eslint-disable-line
  return server;
}

export default createServer;

const request = require("request-promise-native");
const fs = require("fs");
const path = require("path");

main();

async function main() {
  const outputPath = path.resolve(
    process.cwd(),
    "content/reason-conf-2019/data.json"
  );

  fs.writeFile(outputPath, JSON.stringify(await getData(), null, 2), err => {
    if (err) {
      return console.error(err);
    }
  });
}

async function getData() {
  try {
    const { files } = await request.get(
      "https://api.github.com/gists/992b79b40cea84ff7ca8efb8cc2350ee",
      {
        headers: {
          "User-Agent": "React-Finland",
        },
        json: true,
      }
    );

    return {
      schedules: JSON.parse(files["schedule.json"].content),
      speakers: JSON.parse(files["speakers.json"].content),
    };
  } catch (err) {
    console.error(err);
  }

  return {};
}
